**自动生成机制**：
```javascript
// 每晚 23:59 自动触发
cron: "59 23 * * *"

async function generateDailyMemory(date) {
  // 1. 收集今天的所有会话
  const sessions = await loadSessionsForDate(date);

  // 2. LLM 提取关键信息
  const analysis = await llm.analyze({
    prompt: `
      分析今天的对话，提取：
      - 用户偏好变化
      - 新学到的知识
      - 重要信息
      - 未完成任务
      - 值得记住的上下文
    `,
    conversations: sessions
  });

  // 3. 生成结构化 Markdown
  const memoryFile = formatMemory(analysis);

  // 4. 保存到 memory/YYYY-MM-DD.md
  await fs.writeFile(
    `~/.clawdbot/agents/${agentId}/memory/${date}.md`,
    memoryFile
  );

  // 5. 可选：更新主 MEMORY.md
  if (analysis.hasLongTermUpdates) {
    await updateMainMemory(analysis.longTermChanges);
  }
}
```

**手动触发**：
```
用户: "记住这一点：我不喜欢早上的会议"
Agent: [分析] → 这是长期偏好
       [操作] → 写入 MEMORY.md
       [确认] "已记住，我会避免安排早上的会议。"
```

### Layer 3: Semantic Search（语义搜索）

#### 为什么需要语义搜索？

**问题**：记忆文件越来越多，如何快速找到相关信息？

```
场景:
用户: "上次我们讨论的那个认证问题解决了吗？"

问题:
- "上次" 是什么时候？可能是几天前、几周前
- "认证问题" 可能在对话中表述为 "OAuth bug"、"登录失败" 等
- 信息可能散布在多个日常记忆文件中
```

**解决方案**：混合搜索系统

#### 技术架构
```
┌─────────────────────────────────────────┐
│         Memory Search System            │
├─────────────────────────────────────────┤
│                                         │
│  ┌──────────────┐  ┌─────────────────┐ │
│  │Vector Search │  │ BM25 Keyword    │ │
│  │(Semantic)    │  │ (Exact Match)   │ │
│  └──────────────┘  └─────────────────┘ │
│         │                  │            │
│         └────────┬─────────┘            │
│                  ▼                      │
│         ┌──────────────┐                │
│         │ Hybrid Rank  │                │
│         └──────────────┘                │
│                  │                      │
│                  ▼                      │
│         ┌──────────────┐                │
│         │   Results    │                │
│         └──────────────┘                │
└─────────────────────────────────────────┘
```

#### Vector Search（向量搜索）
```javascript
// 工作流程
1. 文档切块（Chunking）
   MEMORY.md → 
   [
     "用户姓名: Federico Viticci\n职业: 科技作家",
     "偏好: 简洁直接，避免冗余",
     "工作习惯: 早上7点需要每日简报",
     ...
   ]

2. 生成嵌入（Embeddings）
   chunk → embedding model → [0.23, -0.15, 0.87, ..., 0.42]
   (通常是 768 或 1536 维向量)

3. 存储到向量数据库
   SQLite with vector extension:
   CREATE TABLE embeddings (
     chunk_id TEXT PRIMARY KEY,
     content TEXT,
     embedding BLOB,  -- 向量数据
     source TEXT,     -- 来源文件
     timestamp TEXT
   );

4. 查询时
   用户查询: "认证问题"
   → 生成查询向量
   → 计算余弦相似度
   → 返回最相似的 chunks
```

**配置示例**：
```yaml
agents:
  defaults:
    memorySearch:
      enabled: true
      provider: "openai"  # 或 "local"
      model: "text-embedding-3-small"

      # 本地模型（可选）
      local:
        modelPath: "~/.clawdbot/models/nomic-embed-text-v1.5.Q4_K_M.gguf"

      # 索引配置
      store:
        path: "~/.clawdbot/memory/{agentId}.sqlite"

      # 分块参数
      chunking:
        maxTokens: 512
        overlap: 50

      # 搜索参数
      topK: 5  # 返回前5个最相关结果
```

#### BM25 Keyword Search（关键词搜索）
```javascript
// BM25 算法简化版
function bm25Score(query, document, corpus) {
  // 分词
  const queryTerms = tokenize(query);
  const docTerms = tokenize(document);

  let score = 0;
  for (const term of queryTerms) {
    // 词频（TF）
    const tf = docTerms.filter(t => t === term).length;

    // 逆文档频率（IDF）
    const docsWithTerm = corpus.filter(doc => doc.includes(term)).length;
    const idf = Math.log((corpus.length - docsWithTerm + 0.5) / (docsWithTerm + 0.5));

    // BM25 评分
    score += idf * (tf * (k1 + 1)) / (tf + k1 * (1 - b + b * docLength / avgDocLength));
  }

  return score;
}
```

**优势**：
- **精确匹配**：对于专有名词、ID、代码片段特别有效
- **不依赖语义**：`auth-bug-2024` 能精确找到
- **快速**：不需要计算向量

#### 混合搜索策略
```javascript
async function hybridSearch(query, options = {}) {
  const { topK = 5, vectorWeight = 0.7, bm25Weight = 0.3 } = options;

  // 1. 向量搜索
  const vectorResults = await vectorSearch(query, topK * 2);
  // [
  //   { chunk: "...", score: 0.89, id: "chunk_123" },
  //   { chunk: "...", score: 0.85, id: "chunk_456" },
  //   ...
  // ]

  // 2. BM25 搜索
  const bm25Results = await bm25Search(query, topK * 2);
  // [
  //   { chunk: "...", score: 12.5, id: "chunk_789" },
  //   { chunk: "...", score: 10.2, id: "chunk_123" },
  //   ...
  // ]

  // 3. 归一化分数
  const normalizedVector = normalize(vectorResults);
  const normalizedBM25 = normalize(bm25Results);

  // 4. 加权合并
  const combined = {};
  for (const result of normalizedVector) {
    combined[result.id] = {
      ...result,
      score: result.score * vectorWeight
    };
  }
  for (const result of normalizedBM25) {
    if (combined[result.id]) {
      combined[result.id].score += result.score * bm25Weight;
    } else {
      combined[result.id] = {
        ...result,
        score: result.score * bm25Weight
      };
    }
  }

  // 5. 排序并返回 top K
  return Object.values(combined)
    .sort((a, b) => b.score - a.score)
    .slice(0, topK);
}
```

**实际效果**：
```
查询: "认证问题"

Vector Search 找到:
1. "OAuth 集成失败" (0.85)
2. "登录验证错误" (0.82)
3. "用户权限配置" (0.75)

BM25 Search 找到:
1. "issue #auth-bug-2024" (12.5)
2. "认证问题已在 1月15日修复" (10.2)

混合结果:
1. "OAuth 集成失败" (0.85*0.7 = 0.595)
2. "issue #auth-bug-2024" (norm(12.5)*0.3 = 0.580)
3. "认证问题已在 1月15日修复" (combined)
```

#### 索引管理
```javascript
// 自动索引更新
const watcher = chokidar.watch([
  '~/.clawdbot/agents/*/MEMORY.md',
  '~/.clawdbot/agents/*/memory/*.md'
], {
  ignored: /^\./,
  persistent: true
});

watcher.on('change', debounce(async (path) => {
  console.log(`Memory file changed: ${path}`);
  await reindexFile(path);
}, 1500));  // 1.5秒防抖

// 重新索引流程
async function reindexFile(filePath) {
  // 1. 读取文件
  const content = await fs.readFile(filePath, 'utf-8');

  // 2. 检查是否需要重新索引
  const fileHash = hash(content);
  const storedHash = await db.getHash(filePath);

  if (fileHash === storedHash) {
    console.log('Content unchanged, skipping');
    return;
  }

  // 3. 删除旧的 chunks
  await db.deleteChunks({ source: filePath });

  // 4. 重新切块
  const chunks = chunkDocument(content, {
    maxTokens: 512,
    overlap: 50
  });

  // 5. 生成 embeddings
  const embeddings = await generateEmbeddings(chunks);

  // 6. 存储到数据库
  await db.insertChunks(chunks.map((chunk, i) => ({
    id: `${filePath}#${i}`,
    content: chunk,
    embedding: embeddings[i],
    source: filePath,
    timestamp: new Date().toISOString()
  })));

  // 7. 更新文件哈希
  await db.setHash(filePath, fileHash);

  console.log(`Reindexed ${chunks.length} chunks from ${filePath}`);
}
```

#### Session Memory 索引（实验性功能）
```yaml
# 可选：索引会话记录
agents:
  defaults:
    memorySearch:
      experimental:
        sessionMemory: true  # 默认 false
      sources:
        - "memory"      # memory/ 目录
        - "sessions"    # sessions/ 目录
```

**工作机制**：
```javascript
// 增量索引会话日志
async function indexSessionUpdates(sessionFile) {
  // 1. 读取新增的行
  const newLines = await readNewLines(sessionFile);

  if (newLines.length < deltaThreshold) {
    // 变化太小，暂不索引
    return;
  }

  // 2. 后台异步索引
  queueBackgroundJob(async () => {
    const chunks = chunkSession(newLines);
    const embeddings = await generateEmbeddings(chunks);
    await db.insertChunks(chunks, embeddings);
  });
}
```

**注意事项**：
- **默认关闭**：会话索引是实验性功能
- **性能影响**：频繁更新可能影响性能
- **异步处理**：索引在后台进行，不阻塞对话
- **结果可能滞后**：搜索结果可能不包含最新会话

### Embedding 缓存优化
```javascript
// 问题：重复生成相同 chunk 的 embeddings 浪费资源

// 解决：内容寻址缓存
async function getCachedEmbedding(chunk) {
  const chunkHash = hash(chunk);

  // 1. 检查缓存
  const cached = await db.getEmbedding(chunkHash);
  if (cached) {
    return cached;
  }

  // 2. 生成新 embedding
  const embedding = await embeddingModel.encode(chunk);

  // 3. 存储到缓存
  await db.setEmbedding(chunkHash, embedding);

  return embedding;
}
```

**效果**：
- 重新索引时，未变化的 chunks 不需要重新生成 embeddings
- 大幅降低 API 调用和成本
- 特别适合频繁更新的文件

## Pre-Compaction Memory Flush

### 上下文窗口限制问题

#### 挑战
```
典型 LLM 上下文窗口: 128K tokens

对话过程:
初始: 50K tokens (系统提示 + 工具 + 记忆)
+1000 用户消息
+1500 AI 响应
+2000 工具调用结果
...
累计: 120K tokens → 即将超限！
```

**问题**：
- 超过限制会导致请求失败
- 简单截断会丢失重要上下文
- 压缩（compaction）会丢失信息

#### 传统压缩方法的缺陷
```javascript
// 简单截断
messages = messages.slice(-50);  // 只保留最后50条
// 问题：可能丢失重要的早期上下文

// 摘要压缩
const summary = await llm.summarize(oldMessages);
messages = [summary, ...recentMessages];
// 问题：摘要可能遗漏细节
```

### Clawdbot 的解决方案

#### Proactive Memory Flush
```javascript
// 配置
{
  agents: {
    defaults: {
      compaction: {
        // 保留的最小 tokens
        reserveTokensFloor: 20000,

        memoryFlush: {
          enabled: true,

          // 软阈值：提前触发
          softThresholdTokens: 4000,

          // 系统提示
          systemPrompt: "Session nearing compaction. Store durable memories now.",

          // 用户提示
          prompt: "Write any lasting notes to memory/YYYY-MM-DD.md; reply with NO_REPLY if nothing to store."
        }
      }
    }
  }
}
```

#### 触发机制
```
计算公式:
flushTrigger = contextWindow - reserveTokensFloor - softThresholdTokens

示例:
contextWindow = 128,000
reserveTokensFloor = 20,000
softThresholdTokens = 4,000

flushTrigger = 128,000 - 20,000 - 4,000 = 104,000 tokens

当会话达到 104K tokens 时，触发 memory flush
```

#### 执行流程
```javascript
async function checkAndFlushMemory(session) {
  // 1. 估算当前 tokens
  const currentTokens = estimateTokens(session.messages);
  const threshold = contextWindow - reserveTokens - softThreshold;

  if (currentTokens < threshold) {
    return;  // 无需 flush
  }

  // 2. 检查是否已经 flush 过
  if (session.memoryFlushed) {
    return;  // 本轮已 flush
  }

  // 3. 添加 flush 提示
  session.messages.push({
    role: "system",
    content: "Session nearing compaction. Store durable memories now."
  });

  session.messages.push({
    role: "user",
    content: "Write any lasting notes to memory/YYYY-MM-DD.md; reply with NO_REPLY if nothing to store."
  });

  // 4. 调用 LLM
  const response = await llm.chat(session.messages);

  // 5. 处理响应
  if (response.content === "NO_REPLY") {
    // 静默完成，用户看不到
    session.memoryFlushed = true;
    // 不添加到消息历史
  } else {
    // 用户可见的消息（罕见）
    session.messages.push(response);
  }

  // 6. 标记已 flush
  session.memoryFlushed = true;

  // 7. 继续正常压缩
  await compactSession(session);
}
```

