### 压缩策略

#### 简单截断 + 摘要
```javascript
async function compactSession(session) {
  const messages = session.messages;
  const targetLength = contextWindow * 0.7;  // 压缩到 70%

  // 1. 永久保留的部分
  const system = messages.filter(m => m.role === "system");
  const recent = messages.slice(-20);  // 最近20条

  // 2. 需要压缩的部分
  const middle = messages.slice(system.length, -20);

  // 3. 生成摘要
  const summary = await llm.summarize({
    messages: middle,
    instruction: "Summarize key points, decisions, and information that may be needed later."
  });

  // 4. 重组
  session.messages = [
    ...system,
    {
      role: "system",
      content: `Previous conversation summary:\n${summary}`
    },
    ...recent
  ];

  // 5. 更新元数据
  session.compactionCount++;
  session.lastCompaction = new Date().toISOString();
}
```

